  "supportive_card_ids": ["C01", "C02", "C10", "C22", "C24", "C46", "C49"],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C01", "C02", "C10", "C22", "C24", "C46", "C49"],
  "claims": [
    {
      "claim": "Fenspiride, the closest spiro oxa-aza structural context, had absolute oral bioavailability of 90% in healthy volunteers, directly supporting F >= 20%.",
      "card_ids": ["C01", "C02"]
    },
    {
      "claim": "PF-592379, a small basic amine with an ether-containing saturated heterocycle, had predicted human F >60%, dog F 61%, and rat F 28%, all at or above the 20% threshold.",
      "card_ids": ["C10", "C22", "C24"]
    },
    {
      "claim": "L4 permeability records show codeine is high-permeability (similar to metoprolol) and dextromethorphan is almost completely absorbed; both are small basic amines with ether/tertiary-amine features, supporting the absorption component for the query.",
      "card_ids": ["C46", "C49"]
    },
    {
      "claim": "Other small basic amine contexts report F at or above 20% (nicotine 44%, diltiazem 38 ± 11%, nalmefene 53%, levofloxacin approaching 100%, vicriviroc excellent, tacrolimus/TDP223206 20–33%).",
      "card_ids": ["C13", "C07", "C03", "C09", "C08", "C12", "C05", "C23", "C25"]
    },
    {
      "claim": "No transferable affirmative low-F evidence exists; the low naloxone Cmax records are structurally distant and not direct F measurements.",
      "card_ids": ["C29", "C30", "C32"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "intestinal_absorption_permeability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C38", "C39", "C40", "C41", "C42", "C43", "C44", "C45", "C46", "C47", "C48", "C49"]
    }
  ],
  "evidence_gaps": [
    "No direct experimental bioavailability measurement exists for the query molecule.",
    "No IV-reference AUC or F calculation is available for the query or for the L4 reference molecules.",
    "First-pass metabolism of the exocyclic methylene and tertiary amine, and the effect of high ionization (pKa 9.58, logD -0.37) on permeability, are not directly characterized.",
    "L4 permeability/fraction-absorbed records are from structurally distinct molecules (codeine, dextromethorphan, sesquiterpenes, M6G) and are not direct systemic-F measurements.",
    "Solubility records in non-physiological vehicles (Labrasol, Cremophor EL, Transcutol P) are not directly relevant to intestinal solubility.",
    "Species differences and close-to-threshold values (PF-592379 rat 28%, tacrolimus/TDP223206 20–33%) leave residual uncertainty."
  ],
  "decision_summary": "Predicted high (F >= 20%) because the closest structural context fenspiride (90%) and the small basic amine PF-592379 (28–61%) support F at or above threshold, and L4 permeability/fraction-absorbed records for codeine and dextromethorphan support adequate intestinal absorption. No transferable affirmative low-F evidence exists. Confidence remains moderate because L4 is not direct systemic-F evidence and first-pass metabolism is uncharacterized."
}

